230	    /**
231	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
232	     * The address is normalized in place (so a required-field check that follows rejects an
233	     * address blank after normalization), the required fields are checked, the telephone and
234	     * email are normalized in place, and the resulting owner is rejected when its derived
235	     * identity key already belongs to another owner. Each rule
236	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
237	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
238	     * to be mapped and saved.
239	     *
240	     * @param ownerFieldsDto the submitted owner fields, normalized in place
241	     */
242	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
243	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
244	        validateRequiredFields(ownerFieldsDto);
245	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
246	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
247	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
248	        rejectDuplicateIdentity(ownerFieldsDto);
249	        rejectCityAtCapacity(ownerFieldsDto.getCity());
250	        rejectDailyLimitExceeded(registrationDate);
251	    }
252	
253	    /**
254	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
255	     * falls on a business day. The date supplied on the request is used when present, otherwise the
256	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
257	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
258	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
259	     * membership number's year segment, the per-day create limit) is computed against.
260	     *
261	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
262	     * @return the effective registration date rolled forward to the next business day
263	     */
264	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
265	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
266	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
267	        return toBusinessDay(effective);
268	    }
269	
270	    /**
271	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
272	     * following Monday, while a weekday is returned unchanged.
273	     *
274	     * @param date the date to adjust
275	     * @return the same date when it is a weekday, otherwise the next Monday
276	     */
277	    private LocalDate toBusinessDay(LocalDate date) {
278	        java.time.DayOfWeek day = date.getDayOfWeek();
279	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
280	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
281	        }
282	        return date;
283	    }
