422	    /**
423	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
424	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
425	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
426	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
427	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
428	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
429	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
430	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
431	     *
432	     * @param telephone the submitted telephone value
433	     * @return the normalized E.164 telephone
434	     */
435	    private String normalizeTelephone(String telephone) {
436	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
437	        String e164;
438	        if (cleaned.startsWith("+")) {
439	            e164 = "+" + cleaned.substring(1);
440	        } else {
441	            String national = cleaned;
442	            if (national.startsWith("0")) {
443	                national = national.substring(1);
444	            }
445	            e164 = "+61" + national;
446	        }
447	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
448	            throw new InvalidFieldsException(List.of("telephone"));
449	        }
450	        validateNationalNumberLength(e164);
451	        return e164;
452	    }
453	
454	    /**
455	     * The required national-number length (the digits after the country code) for each country
456	     * code we recognize: {@code '+61'} (Australia) requires 9 national digits and {@code '+1'}
457	     * (NANP) requires 10. Keyed by the country-code digits without the leading {@code '+'}.
458	     */
459	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
460	        java.util.Map.of("61", 9, "1", 10);
461	
462	    /**
463	     * Validates the national-number length of an already syntactically valid E.164 telephone
464	     * against its country code. For each recognized country code the digits following the code
465	     * must have exactly the expected length ({@code '+61'} => 9 national digits, {@code '+1'} =>
466	     * 10). When the country code is recognized but the national number is the wrong length an
467	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
468	     * response naming the {@code telephone} field. A country code that is not recognized carries
469	     * no per-country length rule and is left to the general 8-to-15-digit E.164 check.
470	     *
471	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
472	     */
473	    private void validateNationalNumberLength(String e164) {
474	        String digits = e164.substring(1);
475	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
476	            .filter(entry -> digits.startsWith(entry.getKey()))
477	            // longest matching country code wins, so a shorter code cannot shadow a longer one
478	            .max(java.util.Comparator.comparingInt(entry -> entry.getKey().length()))
479	            .ifPresent(entry -> {
480	                int nationalLength = digits.length() - entry.getKey().length();
481	                if (nationalLength != entry.getValue()) {
482	                    throw new InvalidFieldsException(List.of("telephone"));
483	                }
484	            });
485	    }
