487	    /**
488	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
489	     * and a domain containing at least one dot, none of the parts holding whitespace or a
490	     * second {@code @}.
491	     */
492	    private static final java.util.regex.Pattern EMAIL_PATTERN =
493	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
