495	    /**
496	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
497	     * accepted and returned unchanged. When present it must be a syntactically valid address;
498	     * the value is stored and returned lower-cased. When present but invalid an
499	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
500	     * response naming the {@code email} field.
501	     *
502	     * @param email the submitted email value, or {@code null} when omitted
503	     * @return the lower-cased email, or {@code null} when none was supplied
504	     */
505	    private String normalizeEmail(String email) {
506	        if (email == null) {
507	            return null;
508	        }
509	        String trimmed = email.trim();
510	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
511	            throw new InvalidFieldsException(List.of("email"));
512	        }
513	        return canonicalEmail(trimmed);
