516	    /**
517	     * Reduces an email to the canonical form used both to store it and to compare it against
518	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
519	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
520	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
521	     * value read back off an existing owner without risk of rejecting it. This is the single
522	     * definition of email identity: two emails denote the same address exactly when they
523	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
524	     * an email already on an existing owner can be compared for equality after both pass through
525	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
526	     *
527	     * @param email the email to canonicalize, or {@code null} when none was supplied
528	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
529	     */
530	    private String canonicalEmail(String email) {
531	        if (email == null) {
532	            return null;
533	        }
534	        return email.trim().toLowerCase(java.util.Locale.ROOT);
535	    }
