537	    /**
538	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
539	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
540	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
541	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
542	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
543	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
544	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
545	     * 400 response naming the {@code postcode} field.
546	     *
547	     * @param postcode the submitted postcode, or {@code null} when omitted
548	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
549	     */
550	    private void validatePostcode(String postcode, String city) {
551	        if (postcode == null) {
552	            return;
553	        }
554	        if (!postcode.matches("^[0-9]{4}$")) {
555	            throw new InvalidFieldsException(List.of("postcode"));
556	        }
557	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
558	        if (range != null) {
559	            int value = Integer.parseInt(postcode);
560	            if (value < range[0] || value > range[1]) {
561	                throw new InvalidFieldsException(List.of("postcode"));
562	            }
563	        }
564	    }
