579	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
580	     */
581	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
582	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
583	            canonicalEmail(ownerFieldsDto.getEmail()), prospectiveHouseholdId(ownerFieldsDto));
584	        boolean taken = this.clinicService.findAllOwners().stream()
585	            .anyMatch(existing -> identityKey.equals(Owner.identityKey(existing.getTelephone(),
586	                canonicalEmail(existing.getEmail()), existing.getHouseholdId())));
