592	    /**
593	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
594	     * set to {@code true}. The identifier is the one the owner would receive
595	     * ({@link #prospectiveHouseholdId(OwnerFieldsDto)}), derived deterministically from its
596	     * household identity so every owner in the same household resolves to the same stable value.
597	     * The new owner receives that value, and any existing household mates that do not yet carry it
598	     * are updated so the whole household shares one identifier. When the request did not opt in the
599	     * owner is left without a household identifier.
600	     *
601	     * @param owner the newly created owner, mutated in place with its household identifier
602	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
603	     */
604	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
605	        String householdId = prospectiveHouseholdId(ownerFieldsDto);
606	        if (householdId == null) {
607	            return;
608	        }
609	        owner.setHouseholdId(householdId);
610	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
611	            if (!householdId.equals(mate.getHouseholdId())) {
612	                mate.setHouseholdId(householdId);
613	                this.clinicService.saveOwner(mate);
614	            }
615	        }
616	    }
