618	    /**
619	     * Derives the {@code householdId} a newly submitted owner would receive, without needing the
620	     * owner to have been mapped or persisted yet. An owner shares a household only when the request
621	     * opts in via {@code sharesHousehold}; when it does, the identifier is derived deterministically
622	     * from the owner's household identity (its {@code lastName} and {@code address}, see
623	     * {@link #householdIdFor(String, String)}), so it matches the value {@link #assignHousehold} will
624	     * later store and every household mate resolves to the same identifier. When the request did not
625	     * opt in the owner belongs to no shared household and {@code null} is returned.
626	     *
627	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
628	     * @return the household identifier the owner would receive, or {@code null} when it shares none
629	     */
630	    private String prospectiveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
631	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
632	            return null;
633	        }
634	        return householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
