637	    /**
638	     * Derives the stable {@code householdId} shared by every owner in the household identified by
639	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
640	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
641	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
642	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
643	     *
644	     * @param lastName the household's last name
645	     * @param address the household's address
646	     * @return the deterministic household identifier
647	     */
648	    private String householdIdFor(String lastName, String address) {
649	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
650	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
651	        return "HH-" + shaHex(key, 16);
652	    }
