654	    /**
655	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
656	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
657	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
658	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
659	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
660	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
661	     * an {@link IllegalStateException} is thrown.
662	     *
663	     * @param input the string to hash
664	     * @param hexChars the number of leading upper-case hex characters to return
665	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
666	     */
667	    private String shaHex(String input, int hexChars) {
668	        try {
669	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
670	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
671	            StringBuilder sb = new StringBuilder();
672	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
673	                sb.append(String.format("%02X", digest[i]));
674	            }
675	            return sb.substring(0, hexChars);
676	        }
677	        catch (java.security.NoSuchAlgorithmException e) {
678	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
679	        }
680	    }
