701	    /**
702	     * Finds every existing owner that shares a household with the given {@code lastName} and
703	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
704	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
705	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
706	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
707	     * every rule that reasons about households.
708	     *
709	     * @param lastName the last name to match on
710	     * @param address the address to match on
711	     * @return the owners sharing the household, in encounter order (possibly empty)
712	     */
713	    private List<Owner> findHouseholdMates(String lastName, String address) {
714	        String normalizedLastName = collapseWhitespace(lastName);
715	        String normalizedAddress = normalizeAddress(address);
716	        return this.clinicService.findAllOwners().stream()
717	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
718	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
719	            .toList();
720	    }
