722	    /**
723	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
724	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
725	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
726	     *
727	     * @param value the value to collapse, or {@code null}
728	     * @return the whitespace-collapsed value, never {@code null}
729	     */
730	    private String collapseWhitespace(String value) {
731	        if (value == null) {
732	            return "";
733	        }
734	        return value.trim().replaceAll("\\s+", " ");
735	    }
