737	    /**
738	     * Common street-type abbreviations expanded during address normalization, keyed by their
739	     * upper-cased token.
740	     */
741	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
742	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
743	
744	    /**
745	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
746	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
747	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
748	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
749	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
750	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
751	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
752	     * everywhere an address is stored or compared.
753	     *
754	     * @param address the submitted address value, or {@code null}
755	     * @return the normalized address, never {@code null}
756	     */
757	    private String normalizeAddress(String address) {
758	        if (address == null) {
759	            return "";
760	        }
761	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
762	        if (collapsed.isEmpty()) {
763	            return "";
764	        }
765	        String[] tokens = collapsed.split(" ");
766	        StringBuilder sb = new StringBuilder(collapsed.length());
767	        for (int i = 0; i < tokens.length; i++) {
768	            if (i > 0) {
769	                sb.append(' ');
770	            }
771	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
772	        }
773	        return sb.toString();
774	    }
